    const item=list[index]; if(!item) return;
    const layout=node('div','op-detail-layout '+(lane==='manga'||lane==='color'||lane==='related'?'is-portrait':''));
    const art=node('div','op-detail-art');addImage(art,item,lane,true);
    const text=node('div','op-detail-copy');
    text.append(node('p','op-detail-kicker',labels[lane]+' · '+numberLabel(item,lane)),heading(item.title||numberLabel(item,lane)));
    const meta=node('p','op-detail-arc',arc.title+' · '+arc.seaLabel);
    text.append(meta);
    const model=MEDIA_SOURCE_MAP.arcs.find(a=>a.seaId===arc.seaId&&a.arcId===arc.id);
    const record=lane==='anime'? model?.animeEpisodes.find(e=>e.broadcastEpisode===Number(item.episode)):
      lane==='live'?model?.liveActionEpisodes.find(e=>e.id===item.id):null;
    if(record?.released){const d=new Date(record.released);if(!Number.isNaN(d.valueOf())){
      text.append(node('p','op-detail-date','Released '+d.toLocaleDateString('en',{year:'numeric',month:'long',day:'numeric',timeZone:'UTC'})));
    }}
    if(item.placement)text.append(node('h3','op-detail-subhead','Placement in the voyage'),node('p','op-detail-summary',item.placement));
    if (arc.summary) { text.append(node('h3','op-detail-subhead','In this chapter of the voyage'),node('p','op-detail-summary',arc.summary)); }
    const facts=node('dl','op-detail-facts');
