    content.append(heading('Ports of the voyage'),node('p','op-detail-summary','Four seas. Thirty-two story arcs. Choose your next destination.'));
    const label=node('label','op-search-label','Find an arc');label.htmlFor='opVoyageSearch';
    const search=node('input','op-explorer-search');search.id='opVoyageSearch';search.type='search';search.autocomplete='off';search.placeholder='Search all 32 arcs';
    const results=node('div','op-voyage-results');content.append(label,search,results);
