        const items=SEA_ARC_DATA[sea].arcs.filter(a=>(a.title+' '+a.place+' '+LABELS[n]).toLocaleLowerCase().includes(q));
        if(!items.length)return;
        items.forEach(a=>{const b=node('button','op-voyage-arc');b.type='button';b.append(node('span','op-voyage-order',String(a.order).padStart(2,'0')),node('span','',a.title));b.onclick=()=>{shut(false);onNavigateArc(sea,a.id);};group.append(b);count++;});
        results.append(group);
