const rowTools=new WeakMap();
function enhanceCatalogue(model,host){
 const lanes={anime:['animeItems','animeRow'],pace:['onePaceItems','paceRow'],manga:['volumeItems','mangaRow'],color:['colorVolumeItems','colorRow'],live:['liveItems','liveRow'],related:['relatedItems','relatedRow']};
 for(const [lane,[field,id]] of Object.entries(lanes)){
   const row=document.getElementById(id);const block=row?.closest('.op-catalogue-lane');if(!block)continue;
   block.querySelector('.op-lane-tools')?.remove();
   if((model[field]||[]).length<2)continue;
   const controls=document.createElement('div');controls.className='op-lane-tools';
   const prev=document.createElement('button'),next=document.createElement('button'),all=document.createElement('button');
   for(const b of [prev,next,all])b.type='button';
   prev.className=next.className='op-row-arrow';all.className='op-browse-all';
   prev.textContent='‹';next.textContent='›';all.textContent='Browse all';
   prev.setAttribute('aria-label','Previous '+lane+' cards');next.setAttribute('aria-label','Next '+lane+' cards');
   prev.setAttribute('aria-controls',id);next.setAttribute('aria-controls',id);
   prev.onclick=()=>row.scrollBy({left:-Math.max(250,row.clientWidth*.85),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});
   next.onclick=()=>row.scrollBy({left:Math.max(250,row.clientWidth*.85),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});
   all.onclick=()=>mediaViewer.catalogue(lane);
   controls.append(prev,next,all);block.querySelector('.op-widget-header').append(controls);
   const update=()=>{prev.disabled=row.scrollLeft<2;next.disabled=row.scrollLeft+row.clientWidth>=row.scrollWidth-2;};
   const old=rowTools.get(row);if(old){row.removeEventListener('scroll',old.update);old.observer?.disconnect();}
   const observer=typeof ResizeObserver==='function'?new ResizeObserver(update):null;
   row.addEventListener('scroll',update,{passive:true});observer?.observe(row);rowTools.set(row,{update,observer});requestAnimationFrame(update);
 }
}
const arcCatalogue=window.OnePieceArcCatalogueApp.createController({
 host:arcPageHost,seaRegistry:SEA_ARC_DATA,manifest:ARTWORK_MANIFEST,mediaMap:MEDIA_SOURCE_MAP,
 assetResolver:resolveSeaAsset,manifestAssetResolver:resolveManifestAsset,
 onBack:requestMapBack,onRendered:enhanceCatalogue,
 onItem(route,item,model){
   const fields={anime:'animeItems',pace:'onePaceItems',manga:'volumeItems',color:'colorVolumeItems',live:'liveItems',related:'relatedItems'};
   for(const [lane,field] of Object.entries(fields)){const list=model[field]||[];const index=list.indexOf(item);if(index!==-1){mediaViewer.details(item,lane,model.arc,list,index);return;}}
 }
});
window.__arcCatalogueQA=arcCatalogue;
mediaViewer=createTributeViewer({getCatalogue:()=>arcCatalogue,resolveArtwork:resolveManifestAsset,
 onNavigateArc:(sea,arc)=>openArcCatalogue(sea,arc),onNavigateSea:sea=>navigate({sea,arc:'',lane:'anime'})});
(function displayFont(){
 const url=resolveSeaAsset('east-blue','assets/fonts/Fraunces-Regular.ttf');if(!url)return;
 const style=document.createElement('style');style.id='opDisplayFontFace';style.textContent='@font-face{font-family:Fraunces;src:url("'+url+'") format("truetype");font-weight:400 700;font-display:swap}';document.head.append(style);
})();
function syncHistory(){
 const route=parseRoute();if(routeHash(route)!==location.hash)history.replaceState(history.state,'',routeHash(route));
 if(currentRoute&&routeKey(currentRoute)===routeKey(route)&&currentRoute.lane===route.lane)return;
 applyRoute(route,{restore:true});
}
function emit(event,detail){
 window.dispatchEvent(new CustomEvent('colosseum:tribute:'+event,{detail}));
 if(window.parent!==window&&location.origin!=='null')window.parent.postMessage({type:'colosseum:tribute:'+event,...detail},location.origin);
}
function reset(){
 mediaViewer.close(false);catalogueViews.clear();mapReturns.clear();
 for(const frame of frames.values())frame.contentWindow?.__opMapState?.reset();
 navigate({sea:'east-blue',arc:'',lane:'anime'},{replace:true});
}
window.addEventListener('keydown',keyboard,true);
// Parent-stage Escape listener is attached later. Consume only a handled child-layer Escape.
window.addEventListener('keydown',e=>{
 if(e.defaultPrevented||e.key!=='Escape'||mediaViewer.isOpen())return;
 if(arcCatalogue.isOpen()){e.preventDefault();e.stopImmediatePropagation();arcCatalogue.close(true);}
},true);
window.addEventListener('popstate',syncHistory);window.addEventListener('hashchange',syncHistory);
window.addEventListener('message',event=>{
 if(event.source!==window.parent||event.source===window||location.origin==='null'||event.origin!==location.origin)return;
 const m=event.data;if(!m||typeof m!=='object')return;
 if(m.type==='colosseum:tribute:reset')reset();
 else if(m.type==='colosseum:tribute:navigate'&&SEA_ORDER.includes(m.sea)){
   if(typeof m.arc==='string'&&m.arc.length<100)openArcCatalogue(m.sea,m.arc);else navigate({sea:m.sea,arc:'',lane:'anime'});
 }
});
const initial=parseRoute();history.replaceState({colosseumTribute:{runtime:runtimeId,serial:++historySerial,hash:routeHash(initial),fromMap:false,parentSerial:null}},'',routeHash(initial));
applyRoute(initial,{autoFocus:false});
window.ColosseumTribute=Object.freeze({version:'1.0.0',reset,
 navigate:({sea,arc='',lane='anime'}={})=>SEA_ORDER.includes(sea)?(arc?openArcCatalogue(sea,arc,{focusLane:lane}):navigate({sea,arc:'',lane:'anime'})):false,
 state:()=>Object.freeze({...currentRoute,detailOpen:mediaViewer.isOpen()}),openDirectory:()=>mediaViewer.voyage()});
Object.defineProperty(window,'__combinedAtlasQA',{value:{active:()=>currentSea,loaded:()=>Array.from(frames.keys()),frame:sea=>frames.get(sea)||null,
 switchSea:(sea,writeHash=true)=>SEA_ORDER.includes(sea)?(writeHash?navigate({sea,arc:'',lane:'anime'}):applyRoute({sea,arc:'',lane:'anime'})):false,
 openArc:openArcCatalogue,closeArc:()=>arcCatalogue.close(true),arcCatalogue:()=>arcCatalogue,
 artworkSeam:()=>window.OnePieceArtworkSeam,sourcePageCount:()=>Object.keys(PAGES).length}});
